:root {
  --amber: #ff9d3d;
  --amber-hot: #ffc06a;
  --red: #ff4d3d;
  --ink: #0b0e12;
  --panel: rgba(13, 17, 22, 0.82);
  --line: rgba(255, 255, 255, 0.13);
  --text: #eef1f4;
  --dim: #9aa3ad;
  --font: "Barlow Condensed", "Oswald", "Arial Narrow", "Roboto Condensed", system-ui, sans-serif;
  --mono: "SFMono-Regular", "Roboto Mono", "DejaVu Sans Mono", monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; height: 100%; overflow: hidden; background: #06080a; }
body { font-family: var(--font); color: var(--text); -webkit-font-smoothing: antialiased; }
#app { position: fixed; inset: 0; }
canvas#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hidden { display: none !important; }
.dim { color: var(--dim); }

#vignette {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 78% 72% at 50% 48%, transparent 46%, rgba(0,0,0,.38) 100%);
  mix-blend-mode: multiply;
}
#damageFlash {
  position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse at 50% 55%, transparent 35%, rgba(255,60,20,.55) 100%);
  transition: opacity .18s ease-out;
}
#damageFlash.on { opacity: 1; transition: opacity .04s ease-in; }

/* ============================= HUD ============================= */
#hud { position: absolute; inset: 0; pointer-events: none; }
.hud-top { position: absolute; top: 24px; left: 28px; right: 26px; display: flex; justify-content: space-between; align-items: flex-start; }

.hud-mission { min-width: 300px; max-width: 430px; padding: 14px 18px 15px; background: linear-gradient(100deg, rgba(9,12,16,.86), rgba(9,12,16,.42)); border-left: 3px solid var(--amber); border-radius: 3px; backdrop-filter: blur(6px); box-shadow: 0 18px 40px rgba(0,0,0,.25); }
.eyebrow { font-size: 10.5px; letter-spacing: .22em; color: var(--amber); font-weight: 700; display: flex; align-items: center; gap: 7px; text-transform: uppercase; }
.eyebrow .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--amber); box-shadow: 0 0 8px var(--amber); }
#missionTitle { font-size: 25px; font-weight: 700; letter-spacing: .01em; margin-top: 5px; text-transform: uppercase; line-height: 1; }
#missionDesc { font-family: var(--mono); font-size: 10.5px; line-height: 1.5; color: #b9c1ca; margin-top: 7px; letter-spacing: .015em; }
.progress { height: 4px; margin-top: 10px; background: rgba(255,255,255,.09); overflow: hidden; border-radius: 2px; }
.progress .fill { height: 100%; width: 0%; background: linear-gradient(90deg, var(--amber), var(--amber-hot)); transition: width .25s ease; }

.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.stat-strip { display: flex; gap: 1px; background: rgba(9,12,16,.72); border: 1px solid var(--line); border-radius: 3px; overflow: hidden; backdrop-filter: blur(6px); }
.stat { padding: 7px 13px 6px; display: flex; flex-direction: column; gap: 1px; min-width: 74px; }
.stat + .stat { border-left: 1px solid var(--line); }
.stat .k { font-size: 8.5px; letter-spacing: .2em; color: var(--dim); }
.stat .v { font-family: var(--mono); font-size: 15px; font-weight: 700; letter-spacing: .02em; }
.stat .v.dim { color: var(--dim); font-size: 13px; }

#minimap { width: 176px; height: 176px; border-radius: 4px; background: rgba(9,12,16,.66); border: 1px solid var(--line); backdrop-filter: blur(4px); }

.hud-bottom { position: absolute; left: 22px; right: 26px; bottom: 18px; display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.speedo-wrap { width: 218px; height: 218px; margin: -32px 0 -18px -14px; }
#speedo { width: 100%; height: 100%; }

.car-status { flex: 1; max-width: 330px; margin-bottom: 8px; background: linear-gradient(90deg, rgba(9,12,16,.7), rgba(9,12,16,.28)); padding: 12px 16px; border-radius: 4px; border: 1px solid var(--line); backdrop-filter: blur(5px); }
.status-block { margin-bottom: 9px; }
.status-head { display: flex; justify-content: space-between; font-size: 9.5px; letter-spacing: .16em; color: #c3cbd3; margin-bottom: 5px; }
.status-head span:last-child { font-family: var(--mono); color: var(--text); }
.bar { height: 5px; background: rgba(255,255,255,.1); border-radius: 1px; overflow: hidden; }
.bar-fill { height: 100%; width: 100%; transition: width .15s linear; }
.bar-fill.damage { background: linear-gradient(90deg, #ffb43d, #ff5a2d); }
.bar-fill.engine { background: linear-gradient(90deg, #5fe0a0, #23b87a); }
.status-meta { display: flex; justify-content: space-between; font-size: 10px; letter-spacing: .14em; color: var(--dim); border-top: 1px solid var(--line); padding-top: 7px; margin-top: 10px; }
#carName { color: var(--amber); font-weight: 700; }

.hints { display: flex; flex-wrap: wrap; gap: 4px 12px; justify-content: flex-end; max-width: 430px; font-size: 10px; letter-spacing: .06em; color: #93a0ad; margin-bottom: 12px; font-family: var(--mono); }
.hints b { color: #e8edf2; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.14); padding: 1px 4px; border-radius: 2px; font-weight: 600; }

.toast { position: absolute; left: 50%; top: 21%; transform: translate(-50%, 12px); opacity: 0; text-align: center; transition: opacity .28s ease, transform .28s ease; min-width: 260px; }
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast .t1 { font-size: 11px; letter-spacing: .3em; color: var(--amber); font-weight: 700; text-transform: uppercase; }
.toast .t2 { font-size: 42px; font-weight: 800; letter-spacing: -.01em; text-transform: uppercase; line-height: 1.04; text-shadow: 0 4px 30px rgba(0,0,0,.55); }
.toast .t3 { font-family: var(--mono); font-size: 11px; color: #bcc6cf; margin-top: 4px; letter-spacing: .06em; }

.slowmo { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%) rotate(-90deg); font-size: 10px; letter-spacing: .5em; color: rgba(255,157,61,.65); font-weight: 700; }
.impact-tag { position: absolute; left: 50%; top: 36%; transform: translate(-50%, 0); font-family: var(--mono); font-weight: 800; font-size: 18px; color: #ffd7a0; opacity: 0; transition: opacity .3s; text-shadow: 0 2px 18px rgba(0,0,0,.8); letter-spacing: .06em; }
.impact-tag.show { opacity: 1; transition: opacity .05s; }

/* ============================= TITLE ============================= */
#titleScreen { position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: space-between; background: linear-gradient(96deg, rgba(4,7,10,.92) 0%, rgba(4,7,10,.72) 38%, rgba(4,7,10,.05) 72%, rgba(4,7,10,.5) 100%); transition: opacity .6s ease; }
#titleScreen.fade { opacity: 0; pointer-events: none; }
.title-scrim { position: absolute; inset: 0; background: radial-gradient(ellipse at 20% 100%, rgba(255,130,40,.16), transparent 55%); pointer-events: none; }
.title-inner { position: relative; padding: 42px 0 0 52px; max-width: 840px; display: flex; flex-direction: column; height: 100%; }

.brand { display: flex; align-items: center; gap: 16px; }
.brand-mark { width: 54px; height: 54px; border: 1px solid rgba(255,157,61,.55); border-radius: 2px; display: grid; place-items: center; font-weight: 800; font-size: 19px; letter-spacing: -.06em; color: var(--amber); background: rgba(255,157,61,.07); transform: skewX(-6deg); }
.brand-mark span { color: rgba(255,255,255,.35); }
.brand-text h1 { font-size: 46px; line-height: .85; letter-spacing: -.02em; font-weight: 800; }
.brand-text h1 span { color: var(--amber); font-weight: 300; }
.tagline { font-family: var(--mono); font-size: 10px; letter-spacing: .27em; text-transform: uppercase; color: #b7c0c8; margin-top: 7px; }
.pitch { margin-top: 26px; max-width: 560px; font-size: 14.5px; line-height: 1.55; color: #c2cad1; font-weight: 300; letter-spacing: .01em; }
.pitch em { color: #fff; font-style: italic; }

.select-head { margin-top: auto; display: flex; align-items: center; gap: 12px; font-size: 10px; letter-spacing: .24em; color: #9fa9b3; font-weight: 700; }
.select-head .rule { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }
#carCount { font-family: var(--mono); color: var(--amber); }

.car-cards { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin-top: 12px; max-width: 720px; }
.car-card { pointer-events: auto; cursor: pointer; text-align: left; background: rgba(11,15,20,.6); border: 1px solid rgba(255,255,255,.1); border-radius: 3px; padding: 11px 12px 12px; color: var(--text); font-family: var(--font); transition: border-color .18s, background .18s, transform .18s; position: relative; overflow: hidden; backdrop-filter: blur(4px); }
.car-card:hover { border-color: rgba(255,157,61,.4); transform: translateY(-2px); }
.car-card.active { border-color: var(--amber); background: linear-gradient(160deg, rgba(255,157,61,.15), rgba(11,15,20,.72)); }
.car-card.active::before { content: ""; position: absolute; left: 0; top: 0; width: 100%; height: 2px; background: var(--amber); }
.cc-class { font-size: 8.5px; letter-spacing: .2em; color: var(--amber); font-weight: 700; }
.cc-name { font-size: 16px; font-weight: 700; line-height: 1.05; margin-top: 3px; text-transform: uppercase; }
.cc-sub { font-family: var(--mono); font-size: 9px; color: var(--dim); margin-top: 3px; }
.cc-stats { display: flex; gap: 6px; margin-top: 8px; }
.cc-stat { flex: 1; }
.cc-stat span { display: block; font-size: 7.5px; letter-spacing: .12em; color: #8b959f; }
.cc-stat i { display: block; height: 2px; margin-top: 3px; background: rgba(255,255,255,.12); }
.cc-stat i b { display: block; height: 100%; background: var(--amber); }
.cc-swatch { position: absolute; right: 11px; top: 11px; width: 13px; height: 13px; border-radius: 50%; border: 1px solid rgba(255,255,255,.35); }

.title-actions { display: flex; align-items: center; gap: 24px; margin: 22px 0 26px; }
.btn { pointer-events: auto; font-family: var(--font); text-transform: uppercase; letter-spacing: .1em; font-weight: 700; border-radius: 2px; cursor: pointer; border: 1px solid transparent; transition: all .16s ease; font-size: 13px; }
.btn.primary { background: var(--amber); color: #150c02; padding: 14px 26px; font-size: 15px; letter-spacing: .12em; display: flex; align-items: center; gap: 14px; box-shadow: 0 8px 30px rgba(255,130,40,.28); }
.btn.primary:hover { background: #ffb45f; transform: translateY(-1px); box-shadow: 0 12px 34px rgba(255,130,40,.4); }
.btn.primary .arrow { font-size: 10px; }
.btn.ghost { background: rgba(255,255,255,.05); border-color: rgba(255,255,255,.15); color: var(--text); padding: 10px 16px; font-size: 11px; }
.btn.ghost:hover { background: rgba(255,255,255,.11); border-color: rgba(255,255,255,.3); }
.btn.ghost.danger:hover { border-color: rgba(255,80,60,.6); color: #ff9f92; }
.btn.small { padding: 7px 14px; font-size: 10px; background: rgba(255,255,255,.06); border-color: var(--line); color: var(--text); }
.btn.small.on { border-color: var(--amber); color: var(--amber); }
.title-note { font-size: 10.5px; line-height: 1.7; color: #a9b3bc; letter-spacing: .04em; }
.title-note b { color: #fff; background: rgba(255,255,255,.1); padding: 0 4px; border-radius: 2px; }
.title-note .dim { font-family: var(--mono); font-size: 9px; margin-top: 2px; }
.title-footer { display: flex; justify-content: space-between; padding: 0 52px 22px; font-size: 8.5px; letter-spacing: .2em; color: #79848e; position: relative; }
.title-footer .dim { font-family: var(--mono); letter-spacing: .08em; }
.title-car-label { position: absolute; right: 6vw; bottom: 15vh; text-align: right; pointer-events: none; }
.title-car-label .big { font-size: 54px; font-weight: 800; letter-spacing: -.01em; text-transform: uppercase; line-height: .9; color: rgba(255,255,255,.92); text-shadow: 0 6px 50px rgba(0,0,0,.7); }
.title-car-label .small { font-family: var(--mono); font-size: 10px; letter-spacing: .23em; color: var(--amber); margin-top: 8px; }

/* ============================= MENU ============================= */
#menu { position: absolute; inset: 0; background: rgba(3,5,7,.55); backdrop-filter: blur(5px); display: flex; align-items: center; justify-content: center; z-index: 30; }
.menu-panel { width: min(880px, 92vw); max-height: 88vh; overflow: auto; background: linear-gradient(170deg, rgba(16,21,27,.97), rgba(9,12,16,.98)); border: 1px solid rgba(255,255,255,.14); border-radius: 4px; padding: 26px 30px 28px; box-shadow: 0 40px 100px rgba(0,0,0,.6); }
.menu-head { display: flex; justify-content: space-between; align-items: flex-start; }
.menu-head h2 { font-size: 26px; letter-spacing: .02em; margin-top: 3px; }
.icon-btn { background: none; border: 1px solid var(--line); color: var(--dim); width: 30px; height: 30px; border-radius: 2px; cursor: pointer; font-size: 12px; }
.icon-btn:hover { color: #fff; border-color: #fff; }
.menu-tabs { display: flex; gap: 2px; margin-top: 20px; border-bottom: 1px solid var(--line); }
.tab { background: none; border: none; color: #8b959f; font-family: var(--font); font-size: 11px; letter-spacing: .16em; font-weight: 700; padding: 9px 16px 10px; cursor: pointer; border-bottom: 2px solid transparent; }
.tab:hover { color: #dfe6ec; }
.tab.active { color: var(--amber); border-bottom-color: var(--amber); }
.tab-body { padding-top: 18px; }
.mission-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.mission-card { text-align: left; background: rgba(255,255,255,.035); border: 1px solid var(--line); border-radius: 3px; padding: 13px 15px; cursor: pointer; color: var(--text); font-family: var(--font); transition: .16s; position: relative; }
.mission-card:hover { border-color: rgba(255,157,61,.55); background: rgba(255,157,61,.06); }
.mission-card.active { border-color: var(--amber); }
.mission-card h3 { font-size: 15px; letter-spacing: .05em; text-transform: uppercase; }
.mission-card p { font-family: var(--mono); font-size: 9.5px; color: var(--dim); line-height: 1.5; margin-top: 4px; }
.mission-card .best { font-family: var(--mono); font-size: 9px; color: var(--amber); margin-top: 6px; letter-spacing: .06em; }
.menu-row { display: flex; gap: 8px; margin-top: 18px; flex-wrap: wrap; }
.controls-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 26px; }
.controls-grid div { display: flex; justify-content: space-between; gap: 14px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 12px; }
.controls-grid b { font-family: var(--mono); font-size: 10px; color: var(--amber); letter-spacing: .04em; }
.controls-grid span { color: #aeb8c2; }
.menu-tip { margin-top: 16px; font-size: 11px; line-height: 1.6; color: var(--dim); }
.menu-tip b { color: #fff; }
.settings-row { display: flex; justify-content: space-between; align-items: center; padding: 11px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 12px; letter-spacing: .06em; color: #c4ccd4; }

/* ============================= LOADING ============================= */
#loading { position: absolute; inset: 0; background: #07090b; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; z-index: 60; transition: opacity .45s ease; }
#loading.fade { opacity: 0; pointer-events: none; }
.load-mark { font-size: 38px; font-weight: 800; color: var(--amber); letter-spacing: -.06em; }
.load-text { font-family: var(--mono); font-size: 10px; letter-spacing: .24em; color: #7f8994; }
.dots::after { content: ""; animation: dots 1.2s steps(4, end) infinite; }
@keyframes dots { 0% { content: ""; } 25% { content: "."; } 50% { content: ".."; } 75% { content: "..."; } }

@media (max-width: 900px) {
  .title-inner { padding: 26px 0 0 24px; }
  .brand-text h1 { font-size: 34px; }
  .car-cards { grid-template-columns: 1fr 1fr; }
  .title-actions { flex-direction: column; align-items: flex-start; gap: 14px; }
  .title-car-label { display: none; }
  .hud-mission { max-width: 280px; min-width: 0; }
  .hints { display: none; }
  .car-status { max-width: 220px; }
  .speedo-wrap { width: 160px; height: 160px; }
  #minimap { width: 130px; height: 130px; }
  .mission-grid { grid-template-columns: 1fr; }
}

import * as THREE from 'three';

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smoothstep = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const TAU = Math.PI * 2;

/* deterministic low-frequency value noise */
function hash2(x, y) {
  let h = x * 374761393 + y * 668265263;
  h = (h ^ (h >> 13)) * 1274126177;
  h = h ^ (h >> 16);
  return ((h & 0x7fffffff) / 0x7fffffff) * 2 - 1;
}
export function noise2(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi), b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}
export function fbm(x, y, oct = 4) {
  let s = 0, amp = 0.5, f = 1;
  for (let i = 0; i < oct; i++) { s += noise2(x * f, y * f) * amp; amp *= 0.5; f *= 2.03; }
  return s;
}

/* ============ world height ============ */
export const PLAY_RADIUS = 235;
export function groundHeight(x, z) {
  const r = Math.hypot(x * 0.86, z);
  const rise = smoothstep(250, 560, r);
  if (rise <= 0.0001) return 0;
  const n = fbm(x * 0.0075 + 12.3, z * 0.0075 - 4.1, 3) * 0.55 + fbm(x * 0.028, z * 0.028, 2) * 0.12;
  return rise * (18 + n * 40) + rise * rise * 46;
}

export function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

/* asphalt with fine grain — used for tiled surfaces */
export function asphaltTexture(size = 512, base = '#2b2e33') {
  const c = makeCanvas(size, size);
  const g = c.getContext('2d');
  g.fillStyle = base;
  g.fillRect(0, 0, size, size);
  const img = g.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * 26;
    d[i] += n; d[i + 1] += n; d[i + 2] += n;
  }
  g.putImageData(img, 0, 0);
  for (let i = 0; i < 120; i++) {
    g.fillStyle = `rgba(255,255,255,${Math.random() * 0.035})`;
    g.beginPath();
    g.arc(Math.random() * size, Math.random() * size, Math.random() * 3 + 0.5, 0, TAU);
    g.fill();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

export function concreteTexture(size = 256) {
  const c = makeCanvas(size, size);
  const g = c.getContext('2d');
  g.fillStyle = '#a9a49b';
  g.fillRect(0, 0, size, size);
  for (let i = 0; i < 2600; i++) {
    const v = 120 + Math.random() * 90;
    g.fillStyle = `rgba(${v},${v - 3},${v - 8},${Math.random() * 0.25})`;
    g.fillRect(Math.random() * size, Math.random() * size, Math.random() * 3 + 1, Math.random() * 3 + 1);
  }
  g.strokeStyle = 'rgba(60,58,55,.25)';
  g.lineWidth = 1;
  for (let i = 0; i < 5; i++) {
    g.beginPath();
    g.moveTo(Math.random() * size, 0);
    g.lineTo(Math.random() * size, size);
    g.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function softDotTexture(size = 64, inner = 'rgba(255,255,255,1)') {
  const c = makeCanvas(size, size);
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  grd.addColorStop(0, inner);
  grd.addColorStop(0.45, 'rgba(255,255,255,.45)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd;
  g.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function gridTexture(cells = 4, size = 512) {
  const c = makeCanvas(size, size);
  const g = c.getContext('2d');
  g.fillStyle = '#26292d';
  g.fillRect(0, 0, size, size);
  const img = g.getImageData(0, 0, size, size), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * 22;
    d[i] += n; d[i + 1] += n; d[i + 2] += n;
  }
  g.putImageData(img, 0, 0);
  g.strokeStyle = 'rgba(230,235,240,.19)';
  g.lineWidth = Math.max(1, size / 340);
  const cell = size / cells;
  for (let i = 0; i <= cells; i++) {
    g.beginPath(); g.moveTo(i * cell, 0); g.lineTo(i * cell, size); g.stroke();
    g.beginPath(); g.moveTo(0, i * cell); g.lineTo(size, i * cell); g.stroke();
  }
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

export function formatTime(sec) {
  if (!isFinite(sec) || sec < 0) return '--:--.--';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  const cs = Math.floor((sec * 100) % 100);
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}

export function formatNum(n) {
  return Math.round(n).toLocaleString('en-US');
}

/* normal from a height function */
export function surfaceNormal(x, z, hFn, out = new THREE.Vector3()) {
  const e = 0.6;
  const hL = hFn(x - e, z), hR = hFn(x + e, z);
  const hD = hFn(x, z - e), hU = hFn(x, z + e);
  out.set(hL - hR, 2 * e, hD - hU).normalize();
  return out;
}

