/* ============================================================
   SHELL — soft, plastically deformable skin lattice
   ============================================================ */
export class Shell {
  constructor(positions, edges, cageTest) {
    const n = positions.length / 3;
    this.nodes = [];
    for (let i = 0; i < n; i++) {
      const p = new THREE.Vector3(positions[i * 3], positions[i * 3 + 1], positions[i * 3 + 2]);
      const cage = cageTest ? cageTest(p) : false;
      this.nodes.push({
        pos: p.clone(),
        home: p.clone(),
        orig: p.clone(),
        vel: new THREE.Vector3(),
        cage,
        k: cage ? 330 : 190,
        c: cage ? 15 : 8,
      });
    }
    this.edges = [];
    for (const [a, b] of edges) {
      const rest = this.nodes[a].orig.distanceTo(this.nodes[b].orig);
      this.edges.push([a, b, rest]);
    }
    this.maxDisp = 0;
    this.avgDisp = 0;
  }

  deform(center, dir, amount, radius, jitter = 0.35) {
    const c = center;
    for (const nd of this.nodes) {
      const d = nd.pos.distanceTo(c);
      if (d > radius) continue;
      const t = 1 - d / radius;
      const w = t * t * (3 - 2 * t);
      const cageScale = nd.cage ? 0.3 : 1;
      const push = amount * w * cageScale;
      const nx = dir.x * push + (Math.random() - 0.5) * push * jitter;
      const ny = dir.y * push + (Math.random() - 0.5) * push * jitter;
      const nz = dir.z * push + (Math.random() - 0.5) * push * jitter;
      nd.pos.x += nx * 1.5; nd.pos.y += ny * 1.5; nd.pos.z += nz * 1.5;
      nd.home.x += nx * 0.82; nd.home.y += ny * 0.82; nd.home.z += nz * 0.82;
      nd.vel.x += nx * 4; nd.vel.y += ny * 4; nd.vel.z += nz * 4;
      // home can't drift absurdly far from original
      const drift = nd.home.distanceTo(nd.orig);
      if (drift > 0.62) nd.home.sub(nd.orig).multiplyScalar(0.62 / drift).add(nd.orig);
    }
  }

  update(dt) {
    dt = Math.min(dt, 1 / 45);
    const nodes = this.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const nd = nodes[i];
      nd.vel.x += ((nd.home.x - nd.pos.x) * nd.k - nd.vel.x * nd.c) * dt;
      nd.vel.y += ((nd.home.y - nd.pos.y) * nd.k - nd.vel.y * nd.c) * dt;
      nd.vel.z += ((nd.home.z - nd.pos.z) * nd.k - nd.vel.z * nd.c) * dt;
      nd.pos.x += nd.vel.x * dt;
      nd.pos.y += nd.vel.y * dt;
      nd.pos.z += nd.vel.z * dt;
    }
    // distance constraints (structural)
    for (let it = 0; it < 2; it++) {
      for (let e = 0; e < this.edges.length; e++) {
        const [a, b, rest] = this.edges[e];
        const A = nodes[a], B = nodes[b];
        const dx = B.pos.x - A.pos.x, dy = B.pos.y - A.pos.y, dz = B.pos.z - A.pos.z;
        const d = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1e-5;
        const diff = (d - rest) / d * 0.42;
        const ox = dx * diff, oy = dy * diff, oz = dz * diff;
        A.pos.x += ox; A.pos.y += oy; A.pos.z += oz;
        B.pos.x -= ox; B.pos.y -= oy; B.pos.z -= oz;
      }
    }
    let maxD = 0, sumD = 0;
    for (const nd of nodes) {
      const dx = nd.pos.x - nd.orig.x, dy = nd.pos.y - nd.orig.y, dz = nd.pos.z - nd.orig.z;
      const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
      if (d > this.maxDisp) this.maxDisp = d;
      sumD += d;
    }
    this.avgDisp = sumD / nodes.length;
  }

  applyToGeometry(geo) {
    const arr = geo.attributes.position.array;
    for (let i = 0; i < this.nodes.length; i++) {
      const p = this.nodes[i].pos;
      arr[i * 3] = p.x; arr[i * 3 + 1] = p.y; arr[i * 3 + 2] = p.z;
    }
    geo.attributes.position.needsUpdate = true;
    geo.computeVertexNormals();
    geo.computeBoundingSphere();
  }

  /* displacement of a local point, weighted by 4 nearest nodes */
  displacementAt(localPos, out = new THREE.Vector3()) {
    const nodes = this.nodes;
    out.set(0, 0, 0);
    let total = 0;
    const best = [];
    for (let i = 0; i < nodes.length; i++) {
      const d = nodes[i].orig.distanceToSquared(localPos);
      if (best.length < 5) {
        best.push([d, i]);
        best.sort((a, b) => a[0] - b[0]);
      } else if (d < best[4][0]) {
        best[4] = [d, i];
        best.sort((a, b) => a[0] - b[0]);
      }
    }
    for (const [d, i] of best) {
      const w = 1 / (d + 0.02);
      const nd = nodes[i];
      out.x += (nd.pos.x - nd.orig.x) * w;
      out.y += (nd.pos.y - nd.orig.y) * w;
      out.z += (nd.pos.z - nd.orig.z) * w;
      total += w;
    }
    return out.multiplyScalar(1 / Math.max(total, 1e-5));
  }
}

/* ============================================================
   MESH BUILDER
   ============================================================ */

function sampleStations(keys, count) {
  const out = [];
  const zMin = keys[0].z, zMax = keys[keys.length - 1].z;
  for (let i = 0; i < count; i++) {
    const t = i / (count - 1);
    const z = lerp(zMin, zMax, t);
    let k = 0;
    while (k < keys.length - 2 && z > keys[k + 1].z) k++;
    const A = keys[k], B = keys[k + 1];
    let f = (z - A.z) / (B.z - A.z);
    f = f * f * (3 - 2 * f);
    out.push({
      z,
      w: lerp(A.w, B.w, f),
      y0: lerp(A.y0, B.y0, f),
      y1: lerp(A.y1, B.y1, f),
      taper: lerp(A.taper, B.taper, f),
      n: lerp(A.n, B.n, f),
    });
  }
  return out;
}

export function buildCar(spec, options = {}) {
  const paintColor = options.color ?? spec.color;
  const STATIONS = 30;
  const A = 26;
  const stations = sampleStations(spec.stations, STATIONS);
  const L = spec.length;

  const num = STATIONS * A + 2;
  const positions = new Float32Array(num * 3);
  const nodeEdges = [];

  const ringIndex = (s, a) => s * A + ((a + A) % A);
  const frontCap = STATIONS * A;
  const rearCap = STATIONS * A + 1;

  for (let s = 0; s < STATIONS; s++) {
    const st = stations[s];
    const cy = (st.y0 + st.y1) / 2;
    const ry = (st.y1 - st.y0) / 2;
    for (let a = 0; a < A; a++) {
      const ang = (a / A) * TAU;
      const co = Math.cos(ang), si = Math.sin(ang);
      const xr = Math.sign(co || 1) * Math.pow(Math.abs(co), 2 / st.n);
      const yr = Math.sign(si || 1) * Math.pow(Math.abs(si), 2 / st.n);
      const t = (yr + 1) / 2;
      const taper = 1 - st.taper * smoothstep(0.42, 1.0, t);
      const idx = (s * A + a) * 3;
      positions[idx] = st.w * xr * taper;
      positions[idx + 1] = cy + ry * yr;
      positions[idx + 2] = st.z;
    }
  }
  // caps
  const first = stations[0], last = stations[STATIONS - 1];
  positions[frontCap * 3] = 0;
  positions[frontCap * 3 + 1] = (last.y0 + last.y1) / 2;
  positions[frontCap * 3 + 2] = last.z;
  positions[rearCap * 3] = 0;
  positions[rearCap * 3 + 1] = (first.y0 + first.y1) / 2;
  positions[rearCap * 3 + 2] = first.z;

  // structural edges
  for (let s = 0; s < STATIONS; s++) {
    for (let a = 0; a < A; a++) {
      nodeEdges.push([ringIndex(s, a), ringIndex(s, a + 1)]);
      if (s < STATIONS - 1) nodeEdges.push([ringIndex(s, a), ringIndex(s + 1, a)]);
    }
  }
  for (let a = 0; a < A; a++) {
    nodeEdges.push([frontCap, ringIndex(STATIONS - 1, a)]);
    nodeEdges.push([rearCap, ringIndex(0, a)]);
  }

  // geometry with per-face material groups
  const verts = Array.from(positions);
  const paintIdx = [], glassIdx = [], trimIdx = [];
  const v0 = new THREE.Vector3(), v1 = new THREE.Vector3(), v2 = new THREE.Vector3();
  const nrm = new THREE.Vector3(), cen = new THREE.Vector3();

  const classify = (ids, normal, center) => {
    const paint = () => paintIdx.push(...ids);
    // dark lower trim
    if (center.y < spec.beltline - 0.42) return trimIdx.push(...ids);
    // glass greenhouse
    if (center.y > spec.beltline + 0.02 && center.z > spec.cabinRear && center.z < spec.cabinFront && normal.y < 0.88) {
      return glassIdx.push(...ids);
    }
    // black bumper ends
    if (center.z > L / 2 - 0.18 || center.z < -L / 2 + 0.18) {
      if (center.y < spec.beltline - 0.1) return trimIdx.push(...ids);
    }
    paint();
  };

  for (let s = 0; s < STATIONS - 1; s++) {
    for (let a = 0; a < A; a++) {
      const ia = ringIndex(s, a), ib = ringIndex(s, a + 1);
      const ic = ringIndex(s + 1, a + 1), id = ringIndex(s + 1, a);
      // outward winding
      let ids = [ia, id, ic];
      v0.fromArray(positions, ia * 3); v1.fromArray(positions, id * 3); v2.fromArray(positions, ic * 3);
      nrm.subVectors(v2, v0).cross(v1.clone().sub(v0)).normalize();
      cen.copy(v0).add(v1).add(v2).multiplyScalar(1 / 3);
      // ensure outward: compare against centerline
      const radial = new THREE.Vector3(cen.x, cen.y - 0.9, 0);
      if (nrm.dot(radial) < 0) { ids = [ia, ic, id]; nrm.negate(); }
      classify(ids, nrm, cen);
      let ids2 = [ia, ic, ib];
      v0.fromArray(positions, ia * 3); v1.fromArray(positions, ic * 3); v2.fromArray(positions, ib * 3);
      nrm.subVectors(v2, v0).cross(v1.clone().sub(v0)).normalize();
      cen.copy(v0).add(v1).add(v2).multiplyScalar(1 / 3);
      if (nrm.dot(new THREE.Vector3(cen.x, cen.y - 0.9, 0)) < 0) { ids2 = [ia, ib, ic]; nrm.negate(); }
      classify(ids2, nrm, cen);
    }
  }
  // caps as trim
  for (let a = 0; a < A; a++) {
    trimIdx.push(frontCap, ringIndex(STATIONS - 1, a + 1), ringIndex(STATIONS - 1, a));
    trimIdx.push(rearCap, ringIndex(0, a), ringIndex(0, a + 1));
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  const indices = [...paintIdx, ...glassIdx, ...trimIdx];
  geo.setIndex(indices);
  geo.addGroup(0, paintIdx.length, 0);
  geo.addGroup(paintIdx.length, glassIdx.length, 1);
  geo.addGroup(paintIdx.length + glassIdx.length, trimIdx.length, 2);
  geo.computeVertexNormals();
  geo.computeBoundingSphere();

  const paintMat = new THREE.MeshPhysicalMaterial({
    color: paintColor, metalness: 0.52, roughness: 0.3,
    clearcoat: 1.0, clearcoatRoughness: 0.12, envMapIntensity: 1.25,
  });
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: 0x081019, metalness: 0.32, roughness: 0.045, envMapIntensity: 2.0,
  });
  const trimMat = new THREE.MeshStandardMaterial({ color: 0x111417, roughness: 0.66, metalness: 0.32 });
  const chromeMat = new THREE.MeshStandardMaterial({ color: 0xc8d0d6, roughness: 0.22, metalness: 1.0 });

  const bodyMesh = new THREE.Mesh(geo, [paintMat, glassMat, trimMat]);
  bodyMesh.castShadow = true;
  bodyMesh.receiveShadow = true;

  const carGroup = new THREE.Group();
  const bodyGroup = new THREE.Group();
  carGroup.add(bodyGroup);
  bodyGroup.add(bodyMesh);

  // cage test: greenhouse + cabin floor are stiff
  const shell = new Shell(positions, nodeEdges, (p) => {
    const inCabin = p.z > spec.cabinRear - 0.1 && p.z < spec.cabinFront + 0.25 && p.y > spec.beltline - 0.12;
    const isRoof = p.y > spec.beltline + 0.25 && Math.abs(p.x) < spec.width * 0.34;
    return inCabin || isRoof;
  });

  /* -------- helper to make attachments that follow the crumpling shell -------- */
  const attachments = [];
  function attach(mesh, localPos, shadows = true) {
    mesh.position.copy(localPos);
    mesh.castShadow = shadows;
    mesh.receiveShadow = false;
    bodyGroup.add(mesh);
    attachments.push({ mesh, base: localPos.clone(), delta: new THREE.Vector3() });
    return mesh;
  }

  const front = L / 2, rear = -L / 2;
  const trim = trimMat, chrome = chromeMat;

  /* grille */
  const grille = attach(new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.34 * (spec.detail.grille || 1), 0.13, 0.05), trim), new THREE.Vector3(0, spec.detail.lightY - 0.18, front + 0.005));
  // grille slats
  for (let i = -2; i <= 2; i++) {
    const slat = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.115, 0.02), chrome);
    slat.position.set(i * 0.055 * (spec.detail.grille || 1), 0, 0.03);
    grille.add(slat);
  }

  /* headlights */
  const headMat = new THREE.MeshStandardMaterial({ color: 0xf5f0dd, emissive: 0xffe9b8, emissiveIntensity: 0.75, roughness: 0.12, metalness: 0.2 });
  const headDim = new THREE.MeshStandardMaterial({ color: 0x2c3238, roughness: 0.4, metalness: 0.5 });
  const lights = [];
  const hx = spec.width * 0.29;
  for (const sx of [-1, 1]) {
    const housing = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.15, 0.06), headDim);
    const lens = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.095, 0.03), headMat);
    lens.position.set(0, 0, 0.038);
    housing.add(lens);
    housing.position.set(sx * hx, spec.detail.lightY, front);
    housing.rotation.y = sx * 0.06;
    attach(housing, housing.position.clone());
  }

  /* taillights */
  const tailMat = new THREE.MeshStandardMaterial({ color: 0x6d0d08, emissive: 0xff1a08, emissiveIntensity: 0.55, roughness: 0.25 });
  const tail = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.68, 0.12, 0.045), tailMat);
  attach(tail, new THREE.Vector3(0, spec.detail.lightY + 0.06, rear - 0.01));
  const tailInner = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.28, 0.04, 0.02), new THREE.MeshBasicMaterial({ color: 0xfff0d0 }));
  tailInner.position.set(0, -0.01, -0.03);
  tailInner.visible = false;
  tail.add(tailInner);

  /* bumpers */
  const bumperF = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.82, 0.2, 0.16), trim);
  attach(bumperF, new THREE.Vector3(0, spec.detail.lightY - 0.4, front - 0.03));
  const bumperR = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.8, 0.2, 0.15), trim);
  attach(bumperR, new THREE.Vector3(0, spec.detail.lightY - 0.35, rear + 0.03));

  /* side skirts */
  for (const sx of [-1, 1]) {
    const skirt = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.1, spec.wheelbase * 0.86), trim);
    attach(skirt, new THREE.Vector3(sx * (spec.width * 0.46), 0.33, 0));
  }

  /* wheel arches */
  const archMat = new THREE.MeshStandardMaterial({ color: 0x0c0e10, roughness: 0.8, metalness: 0.1, side: THREE.DoubleSide });
  const wheelZ = spec.wheelbase / 2;
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const arch = new THREE.Mesh(new THREE.RingGeometry(spec.wheelR * 1.06, spec.wheelR * 1.42, 20, 1, 0, Math.PI), archMat);
      arch.rotation.y = sx * Math.PI / 2;
      arch.rotation.z = 0;
      const pos = new THREE.Vector3(sx * (spec.width * 0.485), spec.wheelR, sz * wheelZ);
      attach(arch, pos, false);
    }
  }

  /* mirrors */
  for (const sx of [-1, 1]) {
    const arm = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.03, 0.03), trim);
    const glass = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.11, 0.16), glassMat);
    glass.position.x = sx * 0.06;
    arm.add(glass);
    attach(arm, new THREE.Vector3(sx * (spec.width * 0.51), spec.beltline + 0.08, spec.cabinFront - 0.3));
  }

  /* exhausts */
  for (let i = 0; i < (spec.detail.exhaust || 1); i++) {
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.05, 0.16, 10), chrome);
    pipe.rotation.x = Math.PI / 2;
    const ox = (i - ((spec.detail.exhaust || 1) - 1) / 2) * 0.5;
    attach(pipe, new THREE.Vector3(ox, 0.32, rear - 0.02));
  }

  if (spec.detail.spoiler) {
    const wing = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.8, 0.04, 0.28), trim);
    const standL = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.16, 0.12), trim);
    const standR = standL.clone();
    standL.position.set(-spec.width * 0.3, -0.09, 0);
    standR.position.set(spec.width * 0.3, -0.09, 0);
    wing.add(standL, standR);
    attach(wing, new THREE.Vector3(0, spec.beltline + 0.12, rear + 0.18));
  }
  if (spec.detail.roofRack) {
    const rack = new THREE.Group();
    for (const sx of [-1, 1]) {
      const bar = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.04, 1.6), trim);
      bar.position.set(sx * 0.35, 0, 0);
      rack.add(bar);
    }
    for (const sz of [-1, 1]) {
      const cross = new THREE.Mesh(new THREE.BoxGeometry(0.74, 0.035, 0.035), trim);
      cross.position.z = sz * 0.7;
      rack.add(cross);
    }
    attach(rack, new THREE.Vector3(0, spec.height - 0.04, -0.4));
  }
  if (spec.detail.hoodScoop) {
    const scoop = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.1, 0.5), trim);
    attach(scoop, new THREE.Vector3(0, spec.beltline - 0.03, 1.28));
  }
  if (spec.detail.twoTone) {
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(spec.width * 0.9, 0.14, 0.02), new THREE.MeshStandardMaterial({ color: 0xefe7d2, roughness: 0.45 }));
    attach(stripe, new THREE.Vector3(0, spec.beltline + 0.28, spec.cabinFront - 0.02));
  }

  /* ============ WHEELS ============ */
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x0e1012, roughness: 0.92, metalness: 0.05 });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0xb9c2c9, roughness: 0.26, metalness: 0.95 });
  const rimDark = new THREE.MeshStandardMaterial({ color: 0x24282c, roughness: 0.5, metalness: 0.7 });
  const brakeMat = new THREE.MeshStandardMaterial({ color: 0x3c4045, roughness: 0.5, metalness: 0.6 });

  const wheels = [];
  for (let i = 0; i < 4; i++) {
    const isFront = i < 2;
    const sx = i % 2 === 0 ? -1 : 1;
    const pivot = new THREE.Group();
    const spin = new THREE.Group();
    pivot.add(spin);
    carGroup.add(pivot);

    const tireGeo = new THREE.CylinderGeometry(spec.wheelR, spec.wheelR, spec.wheelW, 22, 1);
    tireGeo.rotateZ(Math.PI / 2);
    const tire = new THREE.Mesh(tireGeo, tireMat);
    tire.castShadow = true;
    spin.add(tire);

    const rimGeo = new THREE.CylinderGeometry(spec.wheelR * 0.62, spec.wheelR * 0.62, spec.wheelW * 1.02, 18, 1);
    rimGeo.rotateZ(Math.PI / 2);
    spin.add(new THREE.Mesh(rimGeo, rimMat));

    // spokes
    for (let k = 0; k < 5; k++) {
      const spoke = new THREE.Mesh(new THREE.BoxGeometry(spec.wheelW * 1.04, spec.wheelR * 0.85, 0.035), rimDark);
      spoke.rotation.x = (k / 5) * TAU;
      spin.add(spoke);
    }
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(spec.wheelR * 0.2, spec.wheelR * 0.2, spec.wheelW * 1.12, 12), chrome);
    hub.rotation.z = Math.PI / 2;
    spin.add(hub);

    const brake = new THREE.Mesh(new THREE.CylinderGeometry(spec.wheelR * 0.55, spec.wheelR * 0.55, spec.wheelW * 0.5, 16), brakeMat);
    brake.rotation.z = Math.PI / 2;
    spin.add(brake);

    wheels.push({
      pivot, spin, isFront, side: sx,
      local: new THREE.Vector3(sx * (spec.track / 2), spec.wheelR, isFront ? wheelZ : -wheelZ),
      steer: 0, spinAngle: 0, ext: 0.26, spinVel: 0,
      contact: false, slip: 0, groundY: 0, normal: new THREE.Vector3(0, 1, 0),
      worldContact: new THREE.Vector3(), load: 0, broken: false,
    });
  }

  /* cleanup on destroyed */
  function dispose() {
    geo.dispose();
    [paintMat, glassMat, trimMat, chromeMat, headMat, headDim, tailMat, tireMat, rimMat, rimDark, brakeMat].forEach(m => m.dispose());
  }

  return {
    spec, carGroup, bodyGroup, bodyMesh, geo, shell, wheels, attachments, tailMat, headMat, paintMat,
    centerLocal: new THREE.Vector3(0, spec.comY, 0),
    tailInner, dispose,
    updateShell(dt) {
      shell.update(dt);
      shell.applyToGeometry(geo);
      const d = new THREE.Vector3();
      for (const at of attachments) {
        shell.displacementAt(at.base, d);
        at.mesh.position.copy(at.base).add(d);
      }
    },
  };
}

import * as THREE from 'three';
import {
  clamp, lerp, smoothstep, groundHeight, asphaltTexture, concreteTexture,
  gridTexture, makeCanvas, TAU, rand, noise2, fbm,
} from './util.js';

const Y_ROAD = 0.02;
const Y_LINE = 0.045;

function ribbon(scene, points, width, y, material, uRepeat = 40) {
  // points: array of {x,z}; builds a flat strip of given width
  const verts = [], uvs = [], idx = [];
  const n = points.length;
  const pos = new THREE.Vector3(), posN = new THREE.Vector3();
  for (let i = 0; i < n; i++) {
    const p = points[i];
    const next = points[Math.min(n - 1, i + 1)];
    const prev = points[Math.max(0, i - 1)];
    let dx = next.x - prev.x, dz = next.z - prev.z;
    const dl = Math.hypot(dx, dz) || 1;
    dx /= dl; dz /= dl;
    const nx = -dz, nz = dx;
    verts.push(p.x + nx * width / 2, y, p.z + nz * width / 2);
    verts.push(p.x - nx * width / 2, y, p.z - nz * width / 2);
    const u = i / (n - 1) * uRepeat;
    uvs.push(u, 0, u, 1);
  }
  for (let i = 0; i < n - 1; i++) {
    const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
    idx.push(a, b, c, c, b, d);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, material);
  mesh.receiveShadow = true;
  mesh.renderOrder = 1;
  scene.add(mesh);
  return mesh;
}

function ellipsePoints(rx, rz, n = 256) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * TAU;
    pts.push({ x: Math.cos(a) * rx, z: Math.sin(a) * rz });
  }
  return pts;
}

function makeTextTexture(text, w = 512, h = 128, bg = '#15181c', fg = '#ff9d3d', sub = '') {
  const c = makeCanvas(w, h);
  const g = c.getContext('2d');
  g.fillStyle = bg;
  g.fillRect(0, 0, w, h);
  g.strokeStyle = 'rgba(255,255,255,.22)';
  g.lineWidth = 6;
  g.strokeRect(8, 8, w - 16, h - 16);
  g.fillStyle = fg;
  g.font = `800 ${Math.floor(h * 0.42)}px "Arial Narrow", sans-serif`;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, w / 2, h * (sub ? 0.42 : 0.5));
  if (sub) {
    g.fillStyle = '#cfd6dd';
    g.font = `600 ${Math.floor(h * 0.15)}px monospace`;
    g.fillText(sub, w / 2, h * 0.78);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export class World {
  constructor(scene) {
    this.scene = scene;
    this.colliders = [];
    this.cylinders = [];
    this.ramps = [];
    this.checkpoints = [];
    this.trees = [];
    this.dynamic = [];
    this.onPropHit = null;
    this.skidGroups = [];

    this.buildGround();
    this.buildRoads();
    this.buildRamps();
    this.buildCrashZone();
    this.buildProps();
    this.buildScenery();
    this.buildCheckpoints();
  }

  /* ---------------- terrain ---------------- */
  buildGround() {
    const size = 1700, seg = 190;
    const geo = new THREE.PlaneGeometry(size, size, seg, seg);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = new Float32Array(pos.count * 3);
    const c = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const h = groundHeight(x, z);
      pos.setY(i, h);
      const n = fbm(x * 0.05, z * 0.05, 2);
      const rocky = smoothstep(18, 62, h);
      const sand = smoothstep(140, 235, Math.hypot(x, z)) * 0.0;
      c.setRGB(
        lerp(0.215 + n * 0.03, 0.44 + n * 0.05, rocky) + sand,
        lerp(0.32 + n * 0.04, 0.41 + n * 0.04, rocky),
        lerp(0.16 + n * 0.03, 0.35 + n * 0.04, rocky)
      );
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
    }
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.96, metalness: 0.0 });
    this.terrain = new THREE.Mesh(geo, mat);
    this.terrain.receiveShadow = true;
    this.scene.add(this.terrain);

    // distant mountain ring for silhouette
    const ringGeo = new THREE.ConeGeometry(1, 1, 5, 1, true);
    const ringMat = new THREE.MeshStandardMaterial({ color: 0x5c6470, roughness: 1, flatShading: true, side: THREE.DoubleSide });
    const ring = new THREE.InstancedMesh(ringGeo, ringMat, 46);
    const m = new THREE.Matrix4();
    for (let i = 0; i < 46; i++) {
      const a = (i / 46) * TAU + rand(-0.03, 0.03);
      const r = rand(760, 1000);
      const h = rand(120, 300);
      m.makeRotationY(rand(0, TAU));
      m.scale(new THREE.Vector3(rand(140, 260), h, rand(140, 260)));
      m.setPosition(Math.cos(a) * r, h * 0.32 + groundHeight(Math.cos(a) * r, Math.sin(a) * r), Math.sin(a) * r);
      ring.setMatrixAt(i, m);
    }
    ring.instanceMatrix.needsUpdate = true;
    this.scene.add(ring);
  }

  /* ---------------- roads ---------------- */
  buildRoads() {
    const asphalt = asphaltTexture(512, '#30343a');
    asphalt.repeat.set(38, 38);
    const gridTex = gridTexture(1, 512);
    gridTex.repeat.set(18.6, 18.6);
    const gridMat = new THREE.MeshStandardMaterial({ map: gridTex, roughness: 0.92, metalness: 0.02 });
    const gridMesh = new THREE.Mesh(new THREE.PlaneGeometry(186, 186), gridMat);
    gridMesh.rotation.x = -Math.PI / 2;
    gridMesh.position.y = Y_ROAD;
    gridMesh.receiveShadow = true;
    this.scene.add(gridMesh);

    // gridmap outer border
    const border = new THREE.Mesh(new THREE.RingGeometry(0, 1, 4), new THREE.MeshBasicMaterial({ color: 0xd9dfe4 }));
    border.visible = false;
    this.scene.add(border);

    const roadMat = new THREE.MeshStandardMaterial({ map: asphalt, roughness: 0.9, metalness: 0.02, color: 0xbfc3c7 });
    const lineMat = new THREE.MeshBasicMaterial({ color: 0xe7e9e5 });
    const yellowMat = new THREE.MeshBasicMaterial({ color: 0xf1c453 });

    this.roadMat = roadMat;

    // main highway ellipse
    const RX = 205, RZ = 152, W = 20;
    const road = ribbon(this.scene, ellipsePoints(RX, RZ, 300), W, Y_ROAD, roadMat, 60);
    this.highway = road;
    const edgeOuter = ribbon(this.scene, ellipsePoints(RX + W / 2 - 0.7, RZ + W / 2 - 0.7, 300), 0.34, Y_LINE, lineMat, 1);
    const edgeInner = ribbon(this.scene, ellipsePoints(RX - W / 2 + 0.7, RZ - W / 2 + 0.7, 300), 0.34, Y_LINE, lineMat, 1);
    edgeOuter.geometry.dispose(); edgeInner.geometry.dispose();
    this.highwayEdges = [edgeOuter, edgeInner];

    // centre dashes
    const dashPts = [];
    const cols = [];
    const dashGeoVerts = [];
    const dashIdx = [];
    let vi = 0;
    const N = 110;
    for (let i = 0; i < N; i++) {
      const a0 = (i / N) * TAU;
      const a1 = a0 + (TAU / N) * 0.5;
      const p0 = { x: Math.cos(a0) * RX, z: Math.sin(a0) * RZ };
      const p1 = { x: Math.cos(a1) * RX, z: Math.sin(a1) * RZ };
      const dx = p1.x - p0.x, dz = p1.z - p0.z;
      const dl = Math.hypot(dx, dz);
      const nx = -dz / dl * 0.22, nz = dx / dl * 0.22;
      dashGeoVerts.push(p0.x + nx, Y_LINE, p0.z + nz, p0.x - nx, Y_LINE, p0.z - nz,
        p1.x + nx, Y_LINE, p1.z + nz, p1.x - nx, Y_LINE, p1.z - nz);
      dashIdx.push(vi, vi + 1, vi + 2, vi + 2, vi + 1, vi + 3);
      vi += 4;
    }
    const dg = new THREE.BufferGeometry();
    dg.setAttribute('position', new THREE.Float32BufferAttribute(dashGeoVerts, 3));
    dg.setIndex(dashIdx);
    this.scene.add(new THREE.Mesh(dg, yellowMat));

    // radial connectors
    const addRoad = (x, z, w, l, rot = 0) => {
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, l), roadMat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.rotation.z = rot;
      mesh.position.set(x, Y_ROAD + 0.002, z);
      mesh.receiveShadow = true;
      this.scene.add(mesh);
      // edge lines
      for (const s of [-1, 1]) {
        const line = new THREE.Mesh(new THREE.PlaneGeometry(0.3, l), lineMat);
        line.rotation.x = -Math.PI / 2;
        line.position.set(x + Math.cos(rot) * s * (w / 2 - 0.5), Y_LINE, z - Math.sin(rot) * s * (w / 2 - 0.5));
        this.scene.add(line);
      }
    };
    addRoad(0, -119, 18, 58);   // north
    addRoad(0, 119, 18, 58);    // south
    addRoad(142.5, 0, 18, 105, Math.PI / 2); // east
    addRoad(-142.5, 0, 18, 105, Math.PI / 2); // west

    // start / finish line on the grid map
    const startLine = new THREE.Mesh(new THREE.PlaneGeometry(14, 1.2), new THREE.MeshBasicMaterial({ color: 0xf2f2ee }));
    startLine.rotation.x = -Math.PI / 2;
    startLine.position.set(0, Y_LINE, 58);
    this.scene.add(startLine);
    const check = new THREE.Mesh(new THREE.PlaneGeometry(14, 1.2), new THREE.MeshBasicMaterial({ color: 0x15181c }));
    check.rotation.x = -Math.PI / 2;
    check.position.set(0, Y_LINE + 0.001, 57.2);
    check.scale.set(1, 0.5, 1);
    this.scene.add(check);

    // crash-lane dashes from spawn toward the wall
    for (let i = 0; i < 11; i++) {
      const d = new THREE.Mesh(new THREE.PlaneGeometry(0.22, 2.4), yellowMat);
      d.rotation.x = -Math.PI / 2;
      d.position.set(0, Y_LINE, 40 - i * 10);
      this.scene.add(d);
    }
  }

  /* ---------------- ramps ---------------- */
  addRamp(x, z, angle, length, width, height, label) {
    this.ramps.push({ x, z, angle, length, width, height });
    const dir = new THREE.Vector3(Math.sin(angle), 0, Math.cos(angle));
    const right = new THREE.Vector3(dir.z, 0, -dir.x);
    const back = new THREE.Vector3(x, 0, z).sub(dir.clone().multiplyScalar(length / 2));
    const lip = new THREE.Vector3(x, 0, z).add(dir.clone().multiplyScalar(length / 2));

    const verts = [], idx = [], uvs = [];
    // top surface, back edge y=0, lip y=height
    const bl = back.clone().add(right.clone().multiplyScalar(width / 2));
    const br = back.clone().sub(right.clone().multiplyScalar(width / 2));
    const tl = lip.clone().add(right.clone().multiplyScalar(width / 2));
    const tr = lip.clone().sub(right.clone().multiplyScalar(width / 2));
    const push = (v, u, vv) => { verts.push(v.x, v.y, v.z); uvs.push(u, vv); return verts.length / 3 - 1; };
    const a = push(bl.clone().setY(0), 0, 0);
    const b = push(br.clone().setY(0), 1, 0);
    const c = push(tl.clone().setY(height), 0, 1);
    const d = push(tr.clone().setY(height), 1, 1);
    idx.push(a, b, c, c, b, d);
    // sides
    const a2 = push(bl.clone().setY(0), 0, 0), b2 = push(bl.clone().setY(0), 0, 0);
    // simple closed sides as quads
    const sL = verts.length / 3;
    verts.push(bl.x, 0, bl.z, tl.x, height, tl.z, tl.x, 0, tl.z);
    idx.push(sL, sL + 1, sL + 2);
    const sR = verts.length / 3;
    verts.push(br.x, 0, br.z, tr.x, 0, tr.z, tr.x, height, tr.z);
    idx.push(sR, sR + 1, sR + 2);
    // back face
    const sB = verts.length / 3;
    verts.push(bl.x, 0, bl.z, br.x, 0, br.z, tr.x, 0, tr.z);
    idx.push(sB, sB + 1, sB + 2);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const tex = concreteTexture(256);
    tex.repeat.set(3, 3);
    const mat = new THREE.MeshStandardMaterial({ map: tex, color: 0x8f8c85, roughness: 0.92 });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true; mesh.receiveShadow = true;
    this.scene.add(mesh);

    // hazard stripes on the face of the lip
    const stripeTex = makeCanvas(256, 64);
    const g = stripeTex.getContext('2d');
    g.fillStyle = '#e8b33c'; g.fillRect(0, 0, 256, 64);
    g.fillStyle = '#1a1c1e';
    for (let i = -4; i < 14; i++) { g.save(); g.translate(i * 24, 0); g.rotate(-0.5); g.fillRect(0, -30, 12, 130); g.restore(); }
    const st = new THREE.CanvasTexture(stripeTex);
    st.colorSpace = THREE.SRGBColorSpace;
    const lipMesh = new THREE.Mesh(new THREE.PlaneGeometry(width, 0.5), new THREE.MeshStandardMaterial({ map: st, roughness: 0.7 }));
    lipMesh.position.copy(lip); lipMesh.position.y = height - 0.26;
    lipMesh.lookAt(lip.clone().add(dir));
    this.scene.add(lipMesh);

    if (label) {
      const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 0.7), new THREE.MeshBasicMaterial({ map: makeTextTexture(label, 512, 128, '#111417', '#ffd27a'), transparent: false, side: THREE.DoubleSide }));
      sign.position.copy(back).add(right.clone().multiplyScalar(width / 2 + 1.2));
      sign.position.y = 0.9;
      sign.lookAt(sign.position.clone().add(new THREE.Vector3(Math.sin(angle + Math.PI / 2), 0, Math.cos(angle + Math.PI / 2))));
      this.scene.add(sign);
    }
  }

  buildRamps() {
    this.addRamp(64, 36, Math.PI, 12, 9, 3.1, 'JUMP RAMP');
    this.addRamp(-58, -12, -Math.PI / 2, 10, 8, 2.4, 'KICKER');
    this.addRamp(28, -40, Math.PI, 7, 6, 1.5, '');
    this.addRamp(-30, 54, Math.PI / 2, 9, 7, 1.9, '');
  }

